import pandapower as pp
import pandapower.networks as pn
import pandapower.topology as top

# Load the specified network
net = pn.create_cigre_network_mv(with_der="pv_wind")

# Find the bus with the biggest demand
load_elements = ['load', 'asymmetric_load', 'ward', 'xward']
max_load = 0
max_load_bus = None

for element in load_elements:
    if net[element].shape[0] > 0:
        for idx, row in net[element].iterrows():
            bus_load = row['p_mw'] if 'p_mw' in row else row['p_kw'] / 1000
            if bus_load > max_load:
                max_load = bus_load
                max_load_bus = row['bus']

# Increase the biggest demand by 30%
if max_load_bus is not None:
    for element in load_elements:
        if net[element].shape[0] > 0:
            bus_indices = net[element][net[element]['bus'] == max_load_bus].index
            for idx in bus_indices:
                if 'p_mw' in net[element].columns:
                    net[element].at[idx, 'p_mw'] *= 1.3
                elif 'p_kw' in net[element].columns:
                    net[element].at[idx, 'p_kw'] *= 1.3

# Run the AC power flow
pp.runpp(net)

# Report the lowest bus voltage magnitude (p.u.)
min_voltage = net.res_bus['vm_pu'].min()
print(min_voltage)
